// 正式已安装情景的受领→实际公款买粮→携行正路径；只用正常命令与原生bank。
#include "resident/kernel/boundary_dispatch.hpp"
#include "resident/storage/common_codec.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
using V=BoundaryValue;namespace fs=std::filesystem;
// 生产库探针使用异常检查，Release构建也不能跳过真实失败。
void require(bool value,const StableId& why){if(!value)throw std::runtime_error(why);}
template<class T>T must(Outcome<T> value,const StableId& why){require(value.ok,why+": "+value.error.original.code);return std::move(value.value);}
// 原件读取与输出仅是测试附件，不作为会话中的任意世界修改入口。
V read(const fs::path& path){std::ifstream input(path);require(bool(input),"read "+path.string());std::ostringstream text;text<<input.rdbuf();return must(parse_boundary_json(text.str()),"parse input");}
StableId json(const V& value){return must(render_boundary_json(value),"encode output");}
bool ok(const V& value){const auto* entry=value.find("ok");return entry&&entry->as<bool>()&&*entry->as<bool>();}
void write(const fs::path& path,const V& value){std::ofstream output(path);require(bool(output),"write "+path.string());output<<json(value)<<'\n';}
// 所有有限查询使用刚读到的完整当前来源；不导出全世界替代任务页面。
Outcome<LiveOperationResult> query(ResidentReplaySession& world,const StableId& id,const V& args=V{V::Dict{}}){LiveOperation op;op.source=must(world.identity(),"query source");op.payload=boundary::obj({{"query_id",V{id}},{"args",args}});return world.execute_live(op);}
// 请求序号只读正常command_context，不编辑或复制世界状态。
V envelope(ResidentReplaySession& world,const StableId& kind,const V& params){const auto context=must(query(world,"command_context"),"command context").result;return boundary::obj({{"kind",V{kind}},{"params",params},{"actor_id",boundary::field(context,"actor_id","context")},{"request_seq",boundary::field(context,"next_request_seq","context")},{"expected_revision",boundary::field(context,"revision","context")}});}
// 提交走与薄Bridge相同的live口，普通拒绝保其原回执。
V submit(ResidentReplaySession& world,const StableId& kind,const V& params,V::Array& trace){LiveOperation op;op.kind=LiveOperationKind::command;op.source=must(world.identity(),"submit source");op.payload=envelope(world,kind,params);const auto result=must(world.execute_live(op),"submit "+kind).result;trace.push_back(boundary::obj({{"command",op.payload},{"receipt",result}}));require(ok(result),kind+" rejected: "+json(result));return result;}
// 预览不写入收据、资金或任务；失败也必须可保存为可读原领域码。
V preview(ResidentReplaySession& world,const StableId& kind,const V& params){const auto context=must(query(world,"command_context"),"preview context").result;LiveOperation op;op.kind=LiveOperationKind::preview;op.source=must(world.identity(),"preview source");op.payload=boundary::obj({{"kind",V{kind}},{"params",params},{"actor_id",boundary::field(context,"actor_id","context")}});return must(world.execute_live(op),"preview "+kind).result;}
}
// 只完成当前原动作；没有行动时不为了测试额外推进世界。
void finish_current(ResidentReplaySession& world,V::Array& trace){for(int n=0;n<8;++n){auto action=must(query(world,"action_context"),"current action").result;auto* id=action.find("action_id");if(!id||!id->as<StableId>()||id->as<StableId>()->empty())return;submit(world,"advance",V{V::Dict{}},trace);}throw std::runtime_error("bounded action did not finish");}
// 原checkpoint字节直接保留，绝不将手填JSON状态当原生存档。
Bytes save_bank(ResidentReplaySession& world,const fs::path& path){auto bank=must(world.checkpoint(),"save native bank");std::ofstream out(path,std::ios::binary);require(bool(out),"open native bank");out.write(reinterpret_cast<const char*>(bank.data()),static_cast<std::streamsize>(bank.size()));require(bool(out),"write native bank");return bank;}
// 同场真实Need接受与真实商店预算采购；没有货物就不能通过非空携行断言。
int main(int argc,char** argv){fs::path output;V::Array trace;try{
    require(argc==4,"usage: task_cargo_live_probe PREPARED NATIVE_REQUEST OUTPUT");output=argv[3];fs::create_directories(output);const auto catalog=read(argv[1]),request=read(argv[2]);auto world=create_resident_replay_session();require(bool(world),"production factory");auto initialized=world->initialize_native(catalog,request);require(initialized.ok,"native init: "+initialized.error.original.code);
    submit(*world,"talk",boundary::obj({{"role_id",V{"society::role.city_supply"}},{"topic_id",V{"topic.city.grain"}}}),trace);submit(*world,"dialogue_next",V{V::Dict{}},trace);submit(*world,"dialogue_choose",boundary::obj({{"option_id",V{"accept"}}}),trace);submit(*world,"dialogue_confirm",V{V::Dict{}},trace);finish_current(*world,trace);
    auto interaction=must(query(*world,"interaction_view"),"after acceptance").result;if(boundary::get_string(interaction,"phase","interaction")!="scene")submit(*world,"end_interaction",V{V::Dict{}},trace);
    submit(*world,"talk",boundary::obj({{"role_id",V{"society::role.city_supply"}}}),trace);auto accepted=must(query(*world,"interaction_tasks"),"own accepted task").result;write(output/"accepted-task.json",accepted);const auto& rows=boundary::array(boundary::field(accepted,"rows","page"),"rows");require(rows.size()==1&&rows.front().find("task_id"),"one actual county task");const auto task_id=boundary::get_string(rows.front(),"task_id","task"),offer_id=boundary::get_string(rows.front(),"id","task");save_bank(*world,output/"accepted.hmcb");submit(*world,"end_interaction",V{V::Dict{}},trace);
    auto empty=must(query(*world,"task_travel_manifest"),"before purchasing").result;require(boundary::array(boundary::field(empty,"rows","page"),"rows").empty(),"acceptance alone must not create cargo");
    submit(*world,"move_local",boundary::obj({{"place_id",V{"society::place.grain"}}}),trace);finish_current(*world,trace);auto context=boundary::obj({{"place_id",V{"society::place.grain"}},{"provider_actor_id",V{"society::actor.merchant"}},{"role_id",V{"society::role.merchant"}}});submit(*world,"talk",boundary::obj({{"role_id",V{"society::role.merchant"}}}),trace);submit(*world,"dialogue_next",V{V::Dict{}},trace);submit(*world,"dialogue_choose",boundary::obj({{"option_id",V{"trade"}}}),trace);submit(*world,"dialogue_confirm",V{V::Dict{}},trace);auto trading=must(query(*world,"interaction_view"),"formal shop dialogue").result;write(output/"trade-interaction.json",trading);require(boundary::get_string(trading,"phase","interaction")=="trade","author trade phase missing");context=boundary::field(trading,"context","interaction");
    auto trade=must(query(*world,"trade_view",boundary::obj({{"shop_id",V{"society::shop.grain"}},{"provider_actor_id",V{"society::actor.merchant"}}})),"actual trade sources").result;write(output/"trade-sources.json",trade);StableId payer;for(const auto& row:boundary::array(boundary::field(trade,"task_payers","trade"),"payers"))if(boundary::get_string(row,"offer_id","payer")==offer_id)payer=boundary::get_string(row,"wallet_id","payer");require(!payer.empty(),"actual accepted task payer missing");
    auto purchase=boundary::obj({{"shop_id",V{"society::shop.grain"}},{"item_id",V{"society::item.millet"}},{"quantity",V{Integer{4}}},{"side",V{"buy"}},{"payer_wallet_id",V{payer}},{"context",context}});auto quote=preview(*world,"trade",purchase);write(output/"purchase-preview.json",quote);require(ok(quote),"task purchase quote: "+json(quote));purchase.as<V::Dict>()->emplace_back("quoted_total",boundary::field(quote,"total","quote"));purchase.as<V::Dict>()->emplace_back("market_revision",boundary::field(quote,"market_revision","quote"));submit(*world,"trade",purchase,trace);finish_current(*world,trace);save_bank(*world,output/"purchased-before-close.hmcb");auto after_trade=must(query(*world,"interaction_view"),"after actual purchase").result;write(output/"after-trade-interaction.json",after_trade);if(boundary::get_string(after_trade,"phase","interaction")=="trade")submit(*world,"close_trade",V{V::Dict{}},trace);
    auto manifest=must(query(*world,"task_travel_manifest"),"real carried cargo").result;write(output/"carrying-page.json",manifest);const auto& cargo=boundary::array(boundary::field(manifest,"rows","manifest"),"rows");require(cargo.size()==1&&boundary::get_string(cargo.front(),"kind","cargo")=="cargo"&&boundary::get_string(cargo.front(),"task_id","cargo")==task_id&&boundary::get_string(cargo.front(),"item_id","cargo")=="society::item.millet"&&boundary::get_int(cargo.front(),"quantity","cargo")==4,"exact actual entrusted cargo");
    const auto bank=save_bank(*world,output/"carrying.hmcb");require(compare_boundary(manifest,must(query(*world,"task_travel_manifest"),"repeat actual cargo").result).exact()&&bank==must(world->checkpoint(),"pure carried page bank"),"cargo query changed world");auto restored=create_resident_replay_session();auto installed=restored->initialize_checkpoint(catalog,bank);require(installed.ok,"restore actual native bank: "+installed.error.original.code);auto recovered=must(query(*restored,"task_travel_manifest"),"restored carried cargo").result;write(output/"restored-carrying-page.json",recovered);require(compare_boundary(boundary::field(manifest,"rows","manifest"),boundary::field(recovered,"rows","manifest")).exact(),"native restore changed actual cargo rows");
    write(output/"commands.json",V{std::move(trace)});write(output/"result.json",boundary::obj({{"ok",V{true}},{"actual_author_source",V{true}},{"task_id",V{task_id}},{"offer_id",V{offer_id}},{"payer_wallet_id",V{payer}},{"actual_entrusted_quantity",V{Integer{4}}},{"original_native_bank_restored",V{true}},{"ui_save_slot_tested",V{false}},{"pure_reads",V{true}},{"tick",V{must(world->identity(),"result identity").tick}}}));std::cout<<"task_cargo_live_probe: authored Need accepted, actual task-budget purchase, four entrusted grain carried, pure manifest and exact native bank restore passed\n";return 0;
}catch(const std::exception& error){if(!output.empty()){write(output/"failed-commands.json",V{trace});write(output/"failure.json",boundary::obj({{"ok",V{false}},{"error",V{StableId(error.what())}}}));}std::cerr<<error.what()<<'\n';return 1;}}
